// One rescue from rescues.txt: find or tell, a square, a radio message
class Rescue
{
    public string Kind { get; set; }      // "find" or "tell"
    public string Square { get; set; }    // the grid square, like 3127
    public string Message { get; set; }   // the radio message

    // Makes one Rescue from a line of rescues.txt, split at each |
    public Rescue(string[] parts)
    {
        Kind = parts[0];
        Square = parts[1];
        Message = parts[2];
    }

    // Reads every rescue in rescues.txt into a list
    public static List<Rescue> LoadAll()
    {
        List<Rescue> rescues = new List<Rescue>();
        string path = Files.Data("rescues.txt");
        if (!File.Exists(path)) return rescues;   // no file: an empty list
        StreamReader reader = new StreamReader(path);
        while (!reader.EndOfStream)
        {
            string line = reader.ReadLine();
            string[] parts = line.Split('|');
            if (parts.Length != 3) continue;    // skip a broken line
            rescues.Add(new Rescue(parts));
        }
        reader.Close();
        return rescues;
    }
}

// ---------- the game-form methods from chapter 9 ----------

// Keeps the result on the map, even if the window is then closed
private void KeepResult()
{
    Expedition.Finish(gameNumber, result);
    finished = true;
    lblScore.Text = "Points: " + result.Score;
}

// Fills in the Round over panel and brings it to the front
private void ShowRoundOver()
{
    lblRoundScore.Text = "You scored " + result.Score
        + " out of 100 points.";
    lblWellList.Text = ListText(result.WentWell,
        "thing that went well", "things that went well");
    lblWrongList.Text = ListText(result.WentWrong,
        "thing that went wrong", "things that went wrong");
    if (result.Score >= 60) Sound.Play("win.wav");
    else Sound.Play("lose.wav");
    pnlRoundOver.Visible = true;
    pnlRoundOver.BringToFront();
}

// Up to 3 lines from a list, then how many more there are
private string ListText(List<string> lines, string one, string many)
{
    if (lines.Count == 0) return "Nothing this time.";
    string text = "";
    for (int i = 0; i < lines.Count && i < 3; i++)
    {
        text = text + "- " + lines[i] + Environment.NewLine;
    }
    int more = lines.Count - 3;
    if (more == 1) text = text + "And 1 more " + one + ".";
    if (more > 1) text = text + "And " + more + " more " + many + ".";
    return text;
}

// Back to the map: closing the window runs FormClosing
private void btnBack_Click(object sender, EventArgs e)
{
    this.Close();
}

// The Round over panel's Back to the map button
private void btnDone_Click(object sender, EventArgs e)
{
    this.Close();
}

// Runs as the window closes, by Back, by Done or by the X
private void frmGridRef_FormClosing(object sender,
    FormClosingEventArgs e)
{
    if (finished) return;    // a finished round closes at once
    DialogResult answer = MessageBox.Show("Leave Grid Ref Rescue? It "
        + "will score nothing, but you can come back and climb it "
        + "again.", "Summit Ready", MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows the speaker picture that matches the sound being on or off
private void ShowSpeaker()
{
    string icon = "icon-speaker-on-64.png";
    if (Sound.Muted) icon = "icon-speaker-muted-64.png";
    picSound.Image = Files.Picture("Icons", icon);
}

// The speaker picture turns the sound off, or back on
private void picSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    ShowSpeaker();
}

private Label[] lblCol = new Label[10];  // numbers along the top
private Label[] lblRow = new Label[10];  // numbers down the side
private PictureBox pin;                // the red pin (tell rescues)
private Random random = new Random();
private Pen gridPen = new Pen(Color.FromArgb(230, 47, 111, 143));
private SolidBrush goodBrush =
    new SolidBrush(Color.FromArgb(115, 62, 142, 65));
private SolidBrush badBrush =
    new SolidBrush(Color.FromArgb(100, 178, 58, 46));
private List<string> wellLines = new List<string>();
private List<string> wrongLines = new List<string>();

// Makes the 20 number labels in the margins, in a for loop
private void MakeNumbers()
{
    for (int c = 0; c < 10; c++)
    {
        lblCol[c] = new Label();
        lblCol[c].AutoSize = false;
        lblCol[c].Text = (27 + c).ToString();
        lblCol[c].Left = 48 + c * KM;
        lblCol[c].Top = 6;
        lblCol[c].Width = KM;
        lblCol[c].Height = 24;
        lblCol[c].TextAlign = ContentAlignment.MiddleCenter;
        lblCol[c].Font = new Font("Segoe UI", 12, FontStyle.Bold);
        lblCol[c].ForeColor = Color.FromArgb(38, 50, 56);
        pnlPlay.Controls.Add(lblCol[c]);

        lblRow[c] = new Label();
        lblRow[c].AutoSize = false;
        lblRow[c].Text = (31 - c).ToString();
        lblRow[c].Left = 8;
        lblRow[c].Top = 32 + c * KM;
        lblRow[c].Width = 36;
        lblRow[c].Height = KM;
        lblRow[c].TextAlign = ContentAlignment.MiddleCenter;
        lblRow[c].Font = new Font("Segoe UI", 12, FontStyle.Bold);
        lblRow[c].ForeColor = Color.FromArgb(38, 50, 56);
        pnlPlay.Controls.Add(lblRow[c]);
    }
}

// Picks 3 find rescues, then 2 tell rescues, in a random order
private void PickRescues()
{
    List<Rescue> finds = new List<Rescue>();
    List<Rescue> tells = new List<Rescue>();
    foreach (Rescue r in Rescue.LoadAll())
    {
        if (r.Kind == "find") finds.Add(r);
        if (r.Kind == "tell") tells.Add(r);
    }
    if (finds.Count < 3 || tells.Count < 2) return;
    int[] f = Mix.ShuffledNumbers(finds.Count);
    int[] t = Mix.ShuffledNumbers(tells.Count);
    for (int i = 0; i < 3; i++) plays.Add(finds[f[i]]);
    for (int i = 0; i < 2; i++) plays.Add(tells[t[i]]);
}

// Puts the next radio message on the screen
private void ShowRescue()
{
    Rescue r = plays[number];
    tries = 0;
    rescueDone = false;
    squares.Clear();
    good.Clear();
    lblRescue.Text = "Rescue " + (number + 1) + " of 5";
    lblRadio.Text = r.Message;
    lblFeedback.Text = "";
    txtRef.Text = "";
    txtRef.Enabled = true;
    btnSend.Enabled = true;
    btnNext.Visible = false;

if (pin != null)
{
    pin.Dispose();   // take away the last pin
    pin = null;
}
bool tell = r.Kind == "tell";
lblRefHead.Visible = tell;
txtRef.Visible = tell;
btnSend.Visible = tell;

    if (tell)
    {
        lblInstruction.Text = "Type the four-figure grid reference "
            + "of the red pin, then press Send to the helicopter.";
        MakePin(r.Square);
        txtRef.Focus();
    }
    else
    {
        lblInstruction.Text = "Click the grid square the radio "
            + "message gives you.";
    }
    picMap.Invalidate();
}

// Puts the red pin at a random point inside square
private void MakePin(string square)
{
    int top = int.Parse(square.Substring(0, 2));
    int side = int.Parse(square.Substring(2, 2));
    pin = new PictureBox();
    pin.Size = new Size(30, 30);
    pin.SizeMode = PictureBoxSizeMode.Zoom;
    pin.BackColor = Color.Transparent;
    pin.Image = Files.Picture("Icons", "icon-pushpin-64.png");
    pin.Left = (top - 27) * KM + 8 + random.Next(18);
    pin.Top = (31 - side) * KM + 2 + random.Next(18);
    picMap.Controls.Add(pin);
}

private void frmGridRef_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();
    picMap.Image = Files.Picture("Map", "mournes-grid-600.png");
    picRadio.Image = Files.Picture("Icons", "icon-radio-64.png");
    MakeNumbers();
    PickRescues();
    if (plays.Count < 5)
    {
        lblRadio.Text = "Grid Ref Rescue needs 3 find and 2 tell "
            + "rescues in Data\\rescues.txt.";
        return;
    }
    ShowRescue();
}

// Draws the coloured squares, then the grid lines, on the map
private void picMap_Paint(object sender, PaintEventArgs e)
{
    Graphics g = e.Graphics;
    for (int i = 0; i < squares.Count; i++)
    {
        int top = int.Parse(squares[i].Substring(0, 2));
        int side = int.Parse(squares[i].Substring(2, 2));
        int x = (top - 27) * KM;
        int y = (31 - side) * KM;
        if (good[i]) g.FillRectangle(goodBrush, x, y, KM, KM);
        else g.FillRectangle(badBrush, x, y, KM, KM);
    }
    for (int i = 0; i <= 10; i++)
    {
        g.DrawLine(gridPen, i * KM, 0, i * KM, 10 * KM);
        g.DrawLine(gridPen, 0, i * KM, 10 * KM, i * KM);
    }
}

// A click on the map: whole-number division finds the square
private void picMap_MouseClick(object sender, MouseEventArgs e)
{
    if (rescueDone || plays.Count < 5) return;
    if (plays[number].Kind != "find") return;
    int column = e.X / KM;
    int row = e.Y / KM;
    if (column > 9 || row > 9) return;    // on the very edge
    string square = (27 + column).ToString() + (31 - row).ToString();
    Judge(square, false);
}

// Send to the helicopter: checks the typed grid reference
private void btnSend_Click(object sender, EventArgs e)
{
    if (rescueDone || plays.Count < 5) return;
    string typed = txtRef.Text.Trim();
    string target = plays[number].Square;
    string swapped = target.Substring(2, 2) + target.Substring(0, 2);
    if (typed == swapped)
    {
        Judge(typed, true);    // checked first: it may be off the map
        return;
    }
    try
    {
        string square = ReadGridRef(typed);
        Judge(square, true);
    }
    catch (GridRefFormatException ex)
    {
        lblFeedback.Text = ex.Message;   // costs nothing
    }
    catch (OffMapException ex)
    {
        lblFeedback.Text = ex.Message;   // costs nothing
    }
    txtRef.Focus();
    txtRef.SelectAll();
}

// Checks text is four digits and on this map, or throws
private string ReadGridRef(string text)
{
    if (text.Length != 4) throw new GridRefFormatException();
    for (int i = 0; i < text.Length; i++)
    {
        if (!char.IsDigit(text[i]))
        {
            throw new GridRefFormatException();
        }
    }
    int top = int.Parse(text.Substring(0, 2));
    int side = int.Parse(text.Substring(2, 2));
    if (top < 27 || top > 36 || side < 22 || side > 31)
    {
        throw new OffMapException(text);
    }
    return text;
}

// Points for a right answer: 20 first time, 10 on the second try
private int RescuePoints()
{
    if (tries == 1) return 20;
    return 10;
}

// Marks one answer: a square clicked, or a grid reference typed
private void Judge(string square, bool tell)
{
    tries++;
    string target = plays[number].Square;
    if (square == target)
    {
        RightAnswer(tell);
        return;
    }
    Sound.Play("wrong.wav");
    squares.Add(square);
    good.Add(false);
    string swapped = target.Substring(2, 2) + target.Substring(0, 2);

    bool turned = square == swapped;
    if (tries == 1)
    {
        string hint = "That is square " + square + ". Take the "
            + "first two numbers from the top of the map and the "
            + "last two from the left side.";
        if (turned)
        {
            hint = "You have the numbers the wrong way round. "
                + "The number along the top of the map comes first.";
        }
        lblFeedback.Text = hint + " Try again.";
        picMap.Invalidate();
        return;
    }
    squares.Add(target);
    good.Add(true);
    ShowAnswer(square, tell, turned);
    EndRescue();
}

// The right square: scores 20 or 10 and sends the helicopter
private void RightAnswer(bool tell)
{
    int points = RescuePoints();
    string target = plays[number].Square;
    total = total + points;
    squares.Add(target);
    good.Add(true);
    Sound.Play("helicopter.wav");
    string when = " on your second try.";
    if (tries == 1) when = " first time.";
    if (tell)
    {
        lblFeedback.Text = "The helicopter is on its way to "
            + target + ". " + points + " points.";
        wellLines.Add("You sent the helicopter to " + target + when);
    }
    else
    {
        lblFeedback.Text = "Right. The radio message gave square "
            + target + ". " + points + " points.";
        wellLines.Add("You found square " + target + when);
    }
    EndRescue();
}

// A second wrong try: shows the right square in green
private void ShowAnswer(string square, bool tell, bool turned)
{
    string target = plays[number].Square;
    string start = "That is square " + square + ". ";
    string help = "Read the number above its column, then the "
        + "number beside its row.";
    if (turned)
    {
        start = "You have the numbers the wrong way round. ";
        help = "The number along the top comes first.";
    }
    if (tell)
    {
        lblFeedback.Text = start + "The pin was in square " + target
            + ", shown in green.";
        wrongLines.Add("You sent the helicopter to " + square
            + ". The pin was in " + target + ". " + help);
    }
    else
    {
        lblFeedback.Text = start + "The radio message gave square "
            + target + ", shown in green.";
        string miss = "You could not find square " + target + ".";
        wrongLines.Add(miss + " " + help);
    }
}

// Settles this rescue and shows the Next rescue button
private void EndRescue()
{
    rescueDone = true;
    txtRef.Enabled = false;
    btnSend.Enabled = false;
    lblScore.Text = "Points: " + total;
    if (number == 4)
    {
        btnNext.Text = "See my score";
        RecordResult();
    }
    else
    {
        btnNext.Text = "Next rescue";
    }
    btnNext.Visible = true;
    btnNext.Focus();
    picMap.Invalidate();
}

// Next rescue, or See my score after rescue 5
private void btnNext_Click(object sender, EventArgs e)
{
    if (number == 4)
    {
        ShowRoundOver();
        return;
    }
    number++;
    ShowRescue();
}

// Adds the feedback to the result, then keeps it
private void RecordResult()
{
    result = new GameResult("Grid Ref Rescue", total);
    result.WentWell.AddRange(wellLines);
    result.WentWrong.AddRange(wrongLines);
    KeepResult();
}
